  "confidence": "high",
  "uncertainties": [],
  "risk": {
    "level": "low",
    "touches": [
      "build",
      "tests"
    ],
    "why": "A mistake in linkage or header declarations could cause compilation failures on some platforms or break symbols expected by tests."
  }
}
